+  SUCCESS: number;
+  FAILED: number;
+  CANCELLED: number;
+  RUNNING: number;
+  QUEUED: number;
+}
+
+function isExecutionStatus(status: string): status is keyof typeof executionChartConfig {
+  return Object.hasOwn(executionChartConfig, status);
