const contents = `const fs = require('node:fs/promises');
const path = require('node:path');
const net = require('node:net');
const { spawn } = require('node:child_process');

const baseUrl = 'http://127.0.0.1:5173';
const apiUrl = 'http://127.0.0.1:8081';
const outputDir = path.resolve(__dirname, 'screenshots');
const edgePath = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

class Cdp {
  constructor(url) {
    this.socket = new WebSocket(url);
    this.sequence = 0;
    this.pending = new Map();
    this.handlers = new Map();
    this.ready = new Promise((resolve, reject) => {
      this.socket.addEventListener('open', resolve, { once: true });
      this.socket.addEventListener('error', reject, { once: true });
    });
    this.socket.addEventListener('message', ({ data }) => {
      const message = JSON.parse(data);
      if (message.id) {
        const entry = this.pending.get(message.id);
        if (!entry) return;
        clearTimeout(entry.timeout);
        this.pending.delete(message.id);
        if (message.error) entry.reject(new Error(message.error.message));
        else entry.resolve(message.result);
      } else {
        for (const handler of this.handlers.get(message.method) ?? []) handler(message.params);
      }
    });
  }

  on(name, handler) {
    const handlers = this.handlers.get(name) ?? [];
    handlers.push(handler);
    this.handlers.set(name, handlers);
  }

  async send(method, params = {}) {
    await this.ready;
    const id = ++this.sequence;
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        this.pending.delete(id);
        reject(new Error('CDP timed out: ' + method));
      }, 20000);
      this.pending.set(id, { resolve, reject, timeout });
      this.socket.send(JSON.stringify({ id, method, params }));
    });
  }

  async evaluate(expression) {
    const result = await this.send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description ?? result.exceptionDetails.text);
    return result.result?.value;
  }

  close() {
    for (const entry of this.pending.values()) {
      clearTimeout(entry.timeout);
      entry.reject(new Error('CDP connection closed'));
    }
    this.pending.clear();
    this.socket.close();
  }
}

async function unusedPort() {
  const server = net.createServer();
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const port = server.address().port;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

async function waitFor(check, label, timeout = 20000) {
  const until = Date.now() + timeout;
  let lastError;
  while (Date.now() < until) {
    try {
      if (await check()) return;
    } catch (error) {
      lastError = error;
    }
    await delay(150);
  }
  throw new Error('Timed out waiting for ' + label + (lastError ? ': ' + lastError.message : ''));
}

async function main() {
  await fs.mkdir(outputDir, { recursive: true });
  const port = await unusedPort();
  const browser = spawn(edgePath, [
    '--headless=new', '--remote-debugging-address=127.0.0.1',
    '--remote-debugging-port=' + port,
    '--user-data-dir=' + path.resolve(__dirname, 'browser-profile'),
    '--no-first-run', '--no-default-browser-check', '--disable-extensions',
    '--disable-background-networking', 'about:blank',
  ], { stdio: 'ignore', windowsHide: true });
  browser.on('error', (error) => { console.error(error.message); });
  let root;
  let page;
  let contextId;
  const report = { source: 'Live local API', screenshots: [], checks: [], runtimeErrors: [], consoleErrors: [] };
  try {
    let version;
    await waitFor(async () => {
      version = await (await fetch('http://127.0.0.1:' + port + '/json/version')).json();
      return Boolean(version.webSocketDebuggerUrl);
    }, 'headless browser');
    root = new Cdp(version.webSocketDebuggerUrl);
    contextId = (await root.send('Target.createBrowserContext', { disposeOnDetach: true })).browserContextId;
    const { targetId } = await root.send('Target.createTarget', { url: 'about:blank', browserContextId: contextId });
    const targets = await (await fetch('http://127.0.0.1:' + port + '/json/list')).json();
    page = new Cdp(targets.find((target) => target.id === targetId).webSocketDebuggerUrl);
    await page.send('Page.enable');
    await page.send('Runtime.enable');
    await page.send('Network.enable');
    await page.send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] });
    page.on('Runtime.exceptionThrown', (event) => report.runtimeErrors.push(event.exceptionDetails.exception?.description ?? event.exceptionDetails.text));
    page.on('Runtime.consoleAPICalled', (event) => {
      if (event.type === 'error') report.consoleErrors.push(event.args.map((arg) => arg.value ?? arg.description ?? '').join(' ').slice(0, 500));
    });
    let viewport = { width: 1440, height: 1000, mobile: false };

    async function setViewport(width, height, mobile = false) {
      viewport = { width, height, mobile };
      await page.send('Emulation.setDeviceMetricsOverride', { ...viewport, deviceScaleFactor: 1 });
    }

    async function go(route, expectedText) {
      await page.send('Page.navigate', { url: baseUrl + route });
      await waitFor(async () => page.evaluate(
        'location.pathname === ' + JSON.stringify(route) +
        ' && document.readyState === "complete" && document.body.innerText.includes(' + JSON.stringify(expectedText) + ')'
      ), route + ' content');
      await page.evaluate('document.fonts.ready.then(() => true)');
      await delay(550);
    }

    async function clickButton(name) {
      const point = await page.evaluate(\`(() => {
        const button = [...document.querySelectorAll('button, [role="button"]')].find((element) =>
          element.getAttribute('aria-label') === \${JSON.stringify(name)} || element.textContent.trim() === \${JSON.stringify(name)});
        if (!button || button.disabled) throw new Error('Button unavailable: ' + \${JSON.stringify(name)});
        const rect = button.getBoundingClientRect();
        return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
      })()\`);
      await page.send('Input.dispatchMouseEvent', { type: 'mousePressed', button: 'left', clickCount: 1, ...point });
      await page.send('Input.dispatchMouseEvent', { type: 'mouseReleased', button: 'left', clickCount: 1, ...point });
      await delay(200);
    }

    async function fill(id, value) {
      await page.evaluate(\`(() => {
        const input = document.getElementById(\${JSON.stringify(id)});
        input.focus();
        Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(input, \${JSON.stringify(value)});
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
      })()\`);
      await delay(100);
    }

    async function capture(name, fullPage = true) {
      const metrics = await page.send('Page.getLayoutMetrics');
      const size = metrics.cssContentSize ?? metrics.contentSize;
      const result = await page.send('Page.captureScreenshot', {
        format: 'png', fromSurface: true, captureBeyondViewport: fullPage,
        clip: { x: 0, y: 0, width: viewport.width, height: fullPage ? Math.min(size.height, 16000) : viewport.height, scale: 1 },
      });
      const screenshotPath = path.join(outputDir, name + '.png');
      await fs.writeFile(screenshotPath, Buffer.from(result.data, 'base64'));
      const layout = await page.evaluate(\`({
        title: document.querySelector('h1')?.textContent.trim(),
        width: innerWidth,
        documentWidth: document.documentElement.scrollWidth,
        mainWidth: Math.round(document.querySelector('main')?.getBoundingClientRect().width ?? 0),
        horizontalOverflow: document.documentElement.scrollWidth > innerWidth,
        activeNavigation: document.querySelector('[aria-label="Admin navigation"] [aria-current="page"]')?.textContent.trim(),
        tableRows: document.querySelectorAll('tbody tr').length
      })\`);
      report.screenshots.push({ name, path: screenshotPath, ...layout });
      if (layout.horizontalOverflow) throw new Error('Page overflows horizontally: ' + name);
      console.log('Captured ' + name + ' (' + viewport.width + 'px)');
    }

    await setViewport(1440, 1000);
    await go('/', 'Visual workflow automation for modern applications.');
    await capture('client-reference', false);

    const loginResponse = await fetch(apiUrl + '/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: 'admin@flowpilot.local', password: <REDACTED> }),
    });
    if (!loginResponse.ok) throw new Error('Local Admin sign-in failed with HTTP ' + loginResponse.status);
    const login = await loginResponse.json();
    const session = login.data;
    if (session.user?.role !== 'ADMIN') throw new Error('The local account is not an Admin.');
    await page.send('Page.addScriptToEvaluateOnNewDocument', { source:
      'localStorage.setItem("flowpilot_token", ' + JSON.stringify(session.accessToken) + ');' +
      'localStorage.setItem("flowpilot_refresh_token", ' + JSON.stringify(session.refreshToken) + ');' +
      'localStorage.setItem("flowpilot_user", ' + JSON.stringify(JSON.stringify(session.user)) + ');'
    });
    await go('/admin', 'Total accounts');
    await capture('admin-overview-desktop');
    await clickButton('Custom range');
    await capture('admin-custom-range-desktop', false);
    await fill('dashboard-from', '2026-01-01T00:00');
    await fill('dashboard-to', '2026-11-14T00:00');
    await clickButton('Apply range');
    const invalidRangeRejected = await page.evaluate('document.body.innerText.includes("Choose a valid date range of up to 90 days.")');
    report.checks.push({ name: 'Reject ranges over 90 days', passed: invalidRangeRejected });
    if (!invalidRangeRejected) throw new Error('Invalid custom date range was accepted.');
    await clickButton('Cancel');

    await go('/admin/users', 'Account ID');
    await capture('admin-users-desktop');
    const accounts = await (await fetch(apiUrl + '/api/admin/users?page=1&pageSize=20', { headers: { Authorization: 'Bearer ' + session.accessToken } })).json();
    const target = accounts.data.items.find((account) => account.id !== session.user.id && account.isActive) ?? session.user;
    await go('/admin/users/' + target.id, 'Account information');
    await capture('admin-user-detail-desktop');
    if (target.id !== session.user.id) {
      await clickButton('Suspend account');
      await capture('admin-account-dialog-desktop', false);
      const confirmationDisabled = await page.evaluate('[...document.querySelectorAll("button")].find((button) => button.textContent.trim() === "Confirm change")?.disabled === true');
      report.checks.push({ name: 'Account changes require a reason', passed: confirmationDisabled });
      if (!confirmationDisabled) throw new Error('Account confirmation is enabled without a reason.');
      await clickButton('Cancel');
    }

    await go('/admin/users', 'Account ID');
    await fill('user-search', 'no-matching-account-admin-ui-check');
    await clickButton('Search');
    await waitFor(() => page.evaluate('document.body.innerText.includes("No matching accounts")'), 'empty search state');
    report.checks.push({ name: 'Account search renders an empty result', passed: true });
    await capture('admin-users-empty-desktop');
    await clickButton('Reset filters');
    await waitFor(() => page.evaluate('document.querySelectorAll("tbody tr").length > 0 && !document.body.innerText.includes("No matching accounts")'), 'reset filters');

    await setViewport(390, 844, true);
    await go('/admin', 'Total accounts');
    await capture('admin-overview-mobile');
    await clickButton('Custom range');
    await capture('admin-custom-range-mobile', false);
    await clickButton('Cancel');
    await go('/admin/users', 'Account ID');
    await capture('admin-users-mobile');
    await go('/admin/users/' + target.id, 'Account information');
    await capture('admin-user-detail-mobile');
    if (target.id !== session.user.id) {
      await clickButton('Suspend account');
      await capture('admin-account-dialog-mobile', false);
      await clickButton('Cancel');
    }

    await setViewport(768, 1024);
    await go('/admin', 'Total accounts');
    await capture('admin-overview-tablet');

    await setViewport(1440, 1000);
    await go('/admin/users/' + session.user.id, 'Account information');
    const selfProtected = await page.evaluate('[...document.querySelectorAll("button")].filter((button) => ["Suspend account", "Change to Client"].includes(button.textContent.trim())).every((button) => button.disabled)');
    report.checks.push({ name: 'Own account changes remain disabled', passed: selfProtected });
    if (!selfProtected) throw new Error('Own account controls are enabled.');

